from __future__ import annotations

"""Causal explanation/evidence layer for Mobile V1 primary decisions.

Evidence aliases intentionally match the authoritative ordering contract names so
an exact order is auditable instead of being labelled Not exposed when the backend
already returned the calculation intermediates.
"""

_STYLE = r'''<style id="yipmanV1AllDecisionEvidenceStyle">
.v1-detail-decision{cursor:pointer;touch-action:manipulation;position:relative;padding-right:46px!important}.v1-detail-decision::after{content:'WHY ›';position:absolute;right:13px;top:15px;color:#75b9eb;font-size:8px;font-weight:1000}.v1-decision-evidence{margin:0 0 9px;border:1px solid #314453;border-radius:14px;background:#101a22;overflow:hidden}.v1-decision-evidence>summary{list-style:none;cursor:pointer;padding:11px 12px;font-size:11px;font-weight:1000;color:#e8f1f7;display:flex;justify-content:space-between}.v1-decision-evidence-body{padding:10px 12px}.v1-decision-section{margin-bottom:12px}.v1-decision-section h4{margin:0 0 5px;color:#8194a3;font-size:8px;font-weight:1000}.v1-decision-section p{margin:0;color:#c0cbd3;font-size:11px;line-height:1.45}.v1-decision-grid{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:6px 10px;font-size:10px}.v1-decision-grid b{color:#8193a1}.v1-decision-grid span{text-align:right;color:#eef4f7;font-weight:1000}.v1-decision-missing{border:1px solid #735d25;background:#241f13;border-radius:10px;padding:9px;color:#e3c36d!important}.v1-decision-flow{font-weight:900;color:#eef4f7!important}.v1-decision-source{color:#8ba0af!important;font-size:9px!important}</style>'''

_SCRIPT = r'''<script id="yipmanV1AllDecisionEvidenceScript">
(()=>{'use strict';const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const txt=(r,s)=>String(r?.querySelector(s)?.textContent||'').trim();const norm=s=>String(s||'').toUpperCase().replace(/[_-]+/g,' ').replace(/\s+/g,' ').trim();
const metric=(r,...labels)=>{const wanted=labels.map(norm);for(const el of r.querySelectorAll('.v1-detail-metrics>div,.v1-force-order-cell,[data-evidence-key]')){const k=norm(el.dataset?.evidenceKey||txt(el,'b'));if(wanted.some(x=>k.includes(x)))return txt(el,'span')||txt(el,'strong')||el.dataset?.evidenceValue||''}return''};const identity=(r,label)=>{for(const el of r.querySelectorAll('.v1-detail-id>div'))if(norm(txt(el,'b')).includes(norm(label)))return txt(el,'span');return''};const n=v=>{const x=parseFloat(String(v||'').replace(/[^0-9.-]/g,''));return Number.isFinite(x)?x:null};const actionPrice=a=>n((String(a).match(/\$\s*([0-9.]+)/)||[])[1]);
function typeOf(a,s){s=norm(a+' '+s);if(/^ORDER\b|^NO ORDER\b/.test(s))return'ORDER';if(s.includes('CLEAR'))return'CLEARANCE';if(s.includes('FRESHNESS'))return'TPR_FRESH';if(s.includes('TPR'))return'TPR_GP';if(s.includes('REG')||s.includes('PRICE'))return'PRICE';return'GENERAL'}
function build(type,action,body){const v={family:identity(body,'FAMILY'),upc:identity(body,'UPC'),oh:metric(body,'EFFECTIVE OH','ORDERING OH USED'),price:metric(body,'CURRENT PRICE'),suggested:metric(body,'SUGGESTED PRICE'),cost:metric(body,'CURRENT COST'),sales:metric(body,'7D SALES'),avg:metric(body,'7D AVG','DAILY FORECAST'),delivery:metric(body,'DELIVERY'),next:metric(body,'NEXT DELIVERY'),preuse:metric(body,'FORECAST USAGE BEFORE DELIVERY','PRE DELIVERY USAGE'),proj:metric(body,'PROJECTED OH AT DELIVERY','PROJECTED OH'),usable:metric(body,'USABLE OH AT DELIVERY'),coverage:metric(body,'FORECAST COVERAGE USAGE','REQUESTED COVERAGE USAGE','COVERAGE DEMAND','COVERAGE USE'),stockout:metric(body,'PRE DELIVERY STOCKOUT QTY'),rounding:metric(body,'PACK ROUNDING','ROUNDING','ORDER UOM')};v.suggested=v.suggested||(actionPrice(action)!=null?'$'+actionPrice(action).toFixed(2):'');let trigger='',comparison='',math='',decision=action,success='',missing=[];
if(type==='ORDER'){const oh=n(v.oh),pre=n(v.preuse),proj=n(v.proj),usable=n(v.usable),cov=n(v.coverage),order=n((action.match(/(?:ORDER)\s+([0-9.]+)/i)||[])[1]);trigger=action.toUpperCase().startsWith('NO ORDER')?'Projected available stock covers the selected delivery window.':'Projected available stock is below expected demand for the selected delivery window.';comparison=`Effective OH ${v.oh||'not exposed'} − pre-delivery usage ${v.preuse||'not exposed'} = projected OH ${v.proj||'not exposed'}; usable OH ${v.usable||v.proj||'not exposed'} vs coverage demand ${v.coverage||'not exposed'}.`;if(cov!=null&&(usable!=null||proj!=null)){const available=usable!=null?usable:Math.max(0,proj);const raw=Math.max(0,cov-available);math=`Raw need = ${cov.toFixed(1)} coverage demand − ${available.toFixed(1)} available at delivery = ${raw.toFixed(1)}. ${v.stockout?'Pre-delivery stockout '+v.stockout+'. ':''}${v.rounding?'Then apply '+v.rounding+'. ':''}${order!=null?'Final displayed order = '+order.toFixed(1)+'.':''}`}else missing.push('forecast_coverage_usage and projected_oh_at_delivery/usable_oh_at_delivery');if(oh==null)missing.push('ordering_oh_used / Effective OH');if(pre==null)missing.push('forecast_usage_before_delivery');success='Success: stock covers demand through the day before next delivery without avoidable overstock or freshness risk.';
}else if(type==='TPR_GP'||type==='PRICE'){const cp=n(v.price),sp=n(v.suggested),c=n(v.cost),av=n(v.avg);trigger='Price review is testing whether another price can improve sustainable GP$/day versus the current REG baseline.';if(cp!=null&&sp!=null&&c!=null){const cm=cp-c,nm=sp-c,be=cm>0&&nm>0?cm/nm:null;comparison=`Current $${cp.toFixed(2)} margin $${cm.toFixed(2)}; proposed $${sp.toFixed(2)} margin $${nm.toFixed(2)}.`;math=be?`Break-even proposed-price velocity = ${be.toFixed(2)}× current velocity.`:'';if(av!=null&&be)math+=` With ${av.toFixed(2)}/day baseline, proposed price needs ≥${(av*be).toFixed(2)}/day.`}else missing.push('current price, suggested price and current cost');missing.push('comparable tested-price event performance when not exposed');success='Success: observed GP$/day at the tested price beats the REG baseline with acceptable velocity.';
}else{trigger=type==='TPR_FRESH'||type==='CLEARANCE'?'Freshness risk requires sell-through intervention.':'Backend raised this action from current item state.';comparison='The detail below uses only live evidence exposed by FULL MYSQL.';math='';success='Success criteria follow the selected operational action.'}
const ev=[['Family',v.family],['UPC',v.upc],['Effective / ordering OH',v.oh],['Pre-delivery usage',v.preuse],['Projected OH @ delivery',v.proj],['Usable OH @ delivery',v.usable],['Coverage demand',v.coverage],['Pre-delivery stockout',v.stockout],['Rounding / UOM',v.rounding],['Current price',v.price],['Suggested price',v.suggested],['Current cost',v.cost],['7D sales',v.sales],['Velocity / forecast',v.avg]].filter(x=>x[1]);return{trigger,comparison,math,decision,success,missing:[...new Set(missing)],ev}}
function apply(){const overlay=document.getElementById('v1DetailOverlay'),body=document.getElementById('v1DetailBody');if(!overlay?.classList.contains('open')||!body)return;const card=body.querySelector('.v1-detail-decision');if(!card)return;const action=txt(card,'strong'),subtitle=txt(card,'p'),sig=action+'|'+identity(body,'FAMILY')+'|'+identity(body,'UPC');if(body.dataset.causalDecisionEvidence===sig)return;body.dataset.causalDecisionEvidence=sig;body.querySelectorAll('.v1-decision-evidence').forEach(x=>x.remove());const d=build(typeOf(action,subtitle),action,body),box=document.createElement('details');box.className='v1-decision-evidence';box.open=true;const grid='<div class="v1-decision-grid">'+d.ev.map(([k,v])=>'<b>'+esc(k)+'</b><span>'+esc(v)+'</span>').join('')+'</div>',missing=d.missing.length?'<p class="v1-decision-missing">Cannot fully prove this exact decision yet. Missing evidence: '+esc(d.missing.join('; '))+'.</p>':'';box.innerHTML='<summary>WHY THIS EXACT DECISION <span>tap to collapse</span></summary><div class="v1-decision-evidence-body"><section class="v1-decision-section"><h4>1 · TRIGGER</h4><p>'+esc(d.trigger)+'</p></section><section class="v1-decision-section"><h4>2 · COMPARISON</h4><p>'+esc(d.comparison)+'</p></section><section class="v1-decision-section"><h4>3 · MATH</h4><p>'+esc(d.math||'Required numerical inputs are not exposed.')+'</p></section><section class="v1-decision-section"><h4>4 · EVIDENCE</h4>'+grid+'</section><section class="v1-decision-section"><h4>5 · WHY THIS DECISION</h4><p class="v1-decision-flow">'+esc(d.decision)+'</p>'+missing+'</section><section class="v1-decision-section"><h4>6 · SUCCESS CRITERIA</h4><p>'+esc(d.success)+'</p></section><section class="v1-decision-section"><h4>SOURCE / LIMITATION</h4><p class="v1-decision-source">Uses only values exposed by the live FULL MYSQL detail. Missing evidence is shown explicitly; the UI never fabricates backend calculations.</p></section></div>';card.insertAdjacentElement('afterend',box);card.onclick=()=>box.open=!box.open}let q=false;const kick=()=>{if(q)return;q=true;requestAnimationFrame(()=>{q=false;apply()})};new MutationObserver(kick).observe(document.documentElement,{subtree:true,childList:true,attributes:true,attributeFilter:['class']});document.addEventListener('click',()=>setTimeout(kick,20),true);setInterval(kick,1200)})();</script>'''

def polish_all_decision_evidence_html(html:str)->str:
    if 'yipmanV1AllDecisionEvidenceStyle' in html:return html
    return html.replace('</head>',_STYLE+'</head>',1).replace('</body>',_SCRIPT+'</body>',1)
